mapper.select:
select date_format(login_time, '%Y-%m-%d') as date,
       count(*) as count
from sys_logininfor
where tenant_id = #{tenantId}
  and status = '0'
  and login_time >= #{start}
  and login_time < #{endExclusive}
group by date_format(login_time, '%Y-%m-%d')
order by date asc

select count(*)
from sys_oper_log
where tenant_id = #{tenantId}
  and status = 1
  and oper_time >= #{start}
  and oper_time < #{endExclusive}

select h.create_time as createTime,
       h.update_time as updateTime,
       coalesce(d.flow_code, '') as flowCode
from flow_his_task h
         left join flow_definition d on d.id = h.definition_id
where h.approver = #{userId}
  and h.del_flag = '0'
  and h.flow_status <> 'copy'
  and h.update_time >= #{start}
  and h.update_time <= #{end}
